import{_ as i,l as r,o as e,c as n,v as t,p,x as o,d as s,i as E,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"机器学习 OPC","description":"","frontmatter":{"title":"机器学习 OPC","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ml-opc.md","filePath":"litho/ml-opc.md","lastUpdated":1789023840000}'),d={name:"litho/ml-opc.md"};function A(c,a,P,B,m,C){const l=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="机器学习-opc" tabindex="-1">机器学习 OPC <a class="header-anchor" href="#机器学习-opc" aria-label="Permalink to &quot;机器学习 OPC&quot;">​</a></h1><div class="epigraph"><p>学习模型可以逼近昂贵的前向核或给逆问题一个靠近的初值；签核仍然要落在校准过的物理成像上，否则幻觉会被刻进掩模。</p><footer>—— 对照计算光刻中机器学习替代胶/成像算子的公开讨论</footer></div><p><a href="/litho/computational-litho-gpu">上一课</a>把全芯片 OPC/ILT 收成同一物理合同下的 GPU 墙钟下降；AI 只被点名为暖启动或胶近似，不能当签核器。缺口是把这条轨写清楚：学什么、在哪一段替换、如何拒绝域外。本课钉机器学习 OPC。学到的修正如何反馈到单元库与设计规则，留给<a href="/litho/dtco-patterning">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>前向核贵在反复求空中像与抗蚀剂轮廓。紧凑胶/蚀刻模型本就是拟合物，不是第一性原理，用网络拟合更多计量在概念上并不犯规。危险是外推：新胶、新硬掩模、新随机配方，网络给出光滑错轮廓，<a href="/litho/ilt-curvilinear">ILT</a> 会把错当目标去反演。端到端「版图进、掩模出」更难保证 MRC 与 PV-band。</p><p>因此问题不是「要不要 ML」，而是：哪一段算子允许被学习替代，哪一段必须物理收口。GPU 解决的是同一模型的吞吐；ML 改变的是模型本身的成本与失效模式。两条加速不要混成一句「AI 光刻」。</p><h3 id="三类替换-签核权不同" tabindex="-1">三类替换，签核权不同 <a class="header-anchor" href="#三类替换-签核权不同" aria-label="Permalink to &quot;三类替换，签核权不同&quot;">​</a></h3><p>算子替代：光学仍用 TCC / 掩模 3D，网络只近似胶或蚀刻偏置——最容易对上计量点。暖启动：网络给出接近的边或 SRAF，物理 OPC/ILT 少迭代几轮。端到端：直接生成掩模，MRC 与窗口难保证，公开讨论里多半停在研究或提议器。量产叙事集中在前两类。</p><p><span class="marginnote">不要把生成模型直接画掩模理解成 cuLitho。上一课的 GPU 路径是物理核映射；本课的 ML 是另一条、必须声明替代了哪一段前向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练数据必须覆盖剂量、焦点、掩模误差角与层别，否则网络背下某一层的指纹。签核协议是：在计量点上对物理模型或硅数据的 EPE 分布；域外（新节距、新胶）拒绝或回退全物理。MRC 投影仍在物理循环里做，不让网络输出免检。</p><p>加速指标是隔夜窗与窗口，不是「推断毫秒」。若暖启动省下的迭代被域外回退吃掉，墙钟不降。与多束数据准备的耦合不变：ML 只会更早把队列堆到掩模厂，若写入与检测跟不上。</p><h3 id="随机与均值" tabindex="-1">随机与均值 <a class="header-anchor" href="#随机与均值" aria-label="Permalink to &quot;随机与均值&quot;">​</a></h3><p>多数公开 ML-OPC 拟合的是均值轮廓。缺孔是极值统计，见<a href="/litho/photon-shot-budget">光子预算</a>。用均值网络去「预测缺陷」需要专门的尾部数据，通常没有。机器学习不自动进入随机签核。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>胶/蚀刻紧凑模型是从计量回归出来的响应面。神经网络是容量更大的响应面。容量大，插值更好，外推更野。物理光学核提供的归纳偏置（低通、TCC 正定）被端到端丢掉之后，网络可以用通带外纹理降低训练 loss，正好踩进 ILT 的零空间——上一课正则要压的那种纹理。所以「先学习再 ILT」若无 MRC/平滑，会比纯物理 ILT 更会过拟合。</p><p>算子替代保留光学偏置，只在本来就是经验的那一段加容量，失败模式接近「换了一套紧凑胶模型」，工厂有校准流程可套。这是它更接近量产的原因。</p><p><span class="marginnote">计算光刻的「正确」以晶圆计量为准。网络与 CPU 参考的比特不一致不可怕；可怕的是在未校准域里给出看起来光滑的 EPE。</span></p>',18)),(e(),p(h,null,{default:o(()=>[E(l,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHYS%5B%22%E7%89%A9%E7%90%86%E5%85%89%E5%AD%A6%E6%A0%B8%22%5D%20--%3E%20FWD%5B%22%E5%89%8D%E5%90%91%E8%BD%AE%E5%BB%93%22%5D%0A%20%20ML%5B%22%E5%AD%A6%E4%B9%A0%E8%83%B6%20%2F%20%E8%9A%80%E5%88%BB%E8%BF%91%E4%BC%BC%22%5D%20--%3E%20FWD%0A%20%20WARM%5B%22%E5%AD%A6%E4%B9%A0%E6%9A%96%E5%90%AF%E5%8A%A8%22%5D%20--%3E%20OPT%5B%22OPC%20%2F%20ILT%20%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20FWD%20--%3E%20OPT%0A%20%20OPT%20--%3E%20SIGN%5B%22%E7%89%A9%E7%90%86%E6%A8%A1%E5%9E%8B%E7%AD%BE%E6%A0%B8%22%5D%0A%20%20END2%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E7%94%9F%E6%88%90%22%5D%20--%3E%20PROP%5B%22%E4%BB%85%E6%8F%90%E8%AE%AE%20%E4%B8%8D%E7%AD%BE%E6%A0%B8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ML-OPC 不降低校准实验成本：训练仍要硅数据。它不提高 NA，不取消 MRC。出口管制与数据保密使「用别厂数据预训练」往往不可行，每家代工厂自己的层指纹很难共享。把某一会议演示的倍速写进所有层的计划，会在最重的 EUV 3D 层上再次超期。</p><p>后课默认：ML 可以加速或近似前向，签核仍是物理合同；设计规则与库如何为这种修正链让路，是 DTCO 的题目。</p><p><span class="marginnote">引用 ML-OPC 时写清：替代的是胶、蚀刻还是端到端，训练域覆盖哪些扰动，签核是否仍跑物理 PV-band。只报推断速度，无法规划 TAPOUT。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>机器学习 OPC 宜做胶/蚀刻近似或暖启动，签核仍用校准成像。</li><li>端到端生成难进量产，因为 MRC 与窗口没有物理合同。</li><li>训练域外必须拒绝；否则 ILT 会把幻觉正则成「干净」纹理。</li><li>均值网络不覆盖随机悬崖；缺陷仍要剂量与胶。</li><li>出处：计算光刻中机器学习替代前向模型的公开讨论；GPU 物理加速见上一课。</li></ul>',6))])}const T=i(d,[["render",A]]);export{u as __pageData,T as default};
